{
  "manifestVersion": 1,
  "name": "support-case",
  "description": "One recorded support case against an entitlement of a service coverage. It is operational evidence a user actor recorded: no customer is authenticated, nothing is emailed, called or messaged, and no channel integration exists. SLA fields are elapsed-time targets computed from the injected UTC clock, never a business-hours or contractual interpretation.",
  "fields": [
    {
      "name": "sourceKey",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "caseNumber",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "serviceCoverageId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "serviceEntitlementId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "contractId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "customerRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "customerContactRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "source",
      "type": "enum",
      "writable": "managed",
      "values": [
        "manual",
        "api"
      ]
    },
    {
      "name": "category",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "priority",
      "type": "enum",
      "writable": "managed",
      "values": [
        "low",
        "normal",
        "high",
        "urgent"
      ]
    },
    {
      "name": "title",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "description",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "status",
      "type": "enum",
      "writable": "managed",
      "values": [
        "new",
        "in_progress",
        "waiting_customer",
        "resolved",
        "closed"
      ]
    },
    {
      "name": "ownerRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "firstResponseDueAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "resolutionDueAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "firstRespondedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "resolvedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "resolutionSummary",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "closedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "openedBy",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "openedAt",
      "type": "timestamp",
      "writable": "managed"
    }
  ]
}

{
  "manifestVersion": 1,
  "name": "service-sla-evaluation",
  "description": "An immutable elapsed-time judgement about one support case, stamped with the exact instant and input values it used. It is never current truth: it is what the clock said when somebody asked. No business-hours calendar, no holidays, no paused clocks and no contractual SLA interpretation exist.",
  "fields": [
    {
      "name": "sourceKey",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "supportCaseId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "serviceCoverageId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "serviceEntitlementId",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "firstResponseState",
      "type": "enum",
      "writable": "managed",
      "values": [
        "met",
        "on_track",
        "at_risk",
        "breached",
        "not_applicable"
      ]
    },
    {
      "name": "resolutionState",
      "type": "enum",
      "writable": "managed",
      "values": [
        "met",
        "on_track",
        "at_risk",
        "breached",
        "not_applicable"
      ]
    },
    {
      "name": "evaluatedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "openedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "firstResponseDueAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "resolutionDueAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "firstRespondedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "resolvedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "basis",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "recordedBy",
      "type": "string",
      "writable": "managed"
    }
  ]
}

{
  "manifestVersion": 1,
  "name": "support-case-activity",
  "description": "Append-only evidence about one support case: a note, a state transition's context, a customer reply a user actor recorded, or an escalation reason. The visibility label is an assertion by the recorder, never an access grant: no customer can read anything here. No attachment bytes are stored.",
  "fields": [
    {
      "name": "sourceKey",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "supportCaseId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "serviceCoverageId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "type",
      "type": "enum",
      "writable": "managed",
      "values": [
        "note",
        "transition",
        "customer_reply",
        "internal_note",
        "escalation"
      ]
    },
    {
      "name": "body",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "evidenceRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "visibility",
      "type": "enum",
      "writable": "managed",
      "values": [
        "internal",
        "customer_visible"
      ]
    },
    {
      "name": "fromStatus",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "toStatus",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "recordedBy",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "occurredAt",
      "type": "timestamp",
      "writable": "managed"
    }
  ]
}

{
  "manifestVersion": 1,
  "name": "service-escalation",
  "description": "Immutable evidence that a human escalated a support case, and why. Nothing is routed, notified or assigned by it: there is no scheduler, no notification channel and no role enforcement, so a target reference is a label rather than a permission.",
  "fields": [
    {
      "name": "sourceKey",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "supportCaseId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "serviceCoverageId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "level",
      "type": "enum",
      "writable": "managed",
      "values": [
        "internal",
        "management",
        "vendor"
      ]
    },
    {
      "name": "reason",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "targetRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "slaEvaluationId",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "evidenceRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "recordedBy",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "recordedAt",
      "type": "timestamp",
      "writable": "managed"
    }
  ]
}

{
  "manifestVersion": 1,
  "name": "service-coverage",
  "description": "An operational support relationship activated from a contract's pending service obligations. It is NOT a signed legal agreement: nobody signed it, it has no envelope, no signer and no artifact, and it neither amends nor replaces the Commercial Contract it was activated from. It records which obligations were consumed, what the customer is covered for and between which dates.",
  "fields": [
    {
      "name": "sourceKey",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "contractId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "activationId",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "orderId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "obligationRefs",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "customerRef",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "customerNameSnapshot",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "companyId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "contactId",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "status",
      "type": "enum",
      "writable": "managed",
      "values": [
        "planned",
        "active",
        "ended"
      ]
    },
    {
      "name": "startDate",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "endDate",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "policyName",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "policyVersion",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "policyFingerprint",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "entitlementCount",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "activatedBy",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "activatedAt",
      "type": "timestamp",
      "writable": "managed"
    },
    {
      "name": "endedReason",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "endedBy",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "endedAt",
      "type": "timestamp",
      "writable": "managed"
    }
  ]
}

{
  "manifestVersion": 1,
  "name": "service-entitlement",
  "description": "Immutable evidence of what one service obligation entitles the customer to: a support tier, the case categories and priorities it covers, and the elapsed-time response targets. It is not a billing unit, not a consumption meter and not a permission: it grants no access to anything and authorizes no charge.",
  "fields": [
    {
      "name": "sourceKey",
      "type": "string",
      "writable": "managed",
      "unique": true
    },
    {
      "name": "serviceCoverageId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "contractId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "serviceObligationId",
      "type": "string",
      "writable": "managed",
      "index": true
    },
    {
      "name": "label",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "supportTier",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "categories",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "priorities",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "firstResponseTargetMinutes",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "resolutionTargetMinutes",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "maxOpenCases",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "quantity",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "startDate",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "endDate",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "policyName",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "policyVersion",
      "type": "integer",
      "writable": "managed"
    },
    {
      "name": "policyFingerprint",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "decisionReason",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "createdBy",
      "type": "string",
      "writable": "managed"
    },
    {
      "name": "issuedAt",
      "type": "timestamp",
      "writable": "managed"
    }
  ]
}
